        return start_owner, end_owner

    start_owner, end_owner = rebuild_owners()

    def merge_with_alignment(ra, rb, mode):
        # mode:
        # 0: endA + startB  (A + B)
        # 1: startA + endB  (reverse A, then endA + startB)
        # 2: endA + endB    (A + reversed B)
        # 3: startA + startB (reverse both, then endA + startB)
        if mode == 0:
            routes[ra] = routes[ra] + routes[rb]
        elif mode == 1:
            routes[ra] = list(reversed(routes[ra])) + routes[rb]
        elif mode == 2:
            routes[ra] = routes[ra] + list(reversed(routes[rb]))
        else:
            routes[ra] = list(reversed(routes[ra])) + list(reversed(routes[rb]))

        routes[rb] = []
        loads[ra] += loads[rb]
        loads[rb] = 0

    merges_done = 0
    max_merges = max(0, len(customers) - max(1, hint)) * 2  # allow extra merges but finite

    for s, i, j in sav:
        if merges_done > max_merges:
            break

        start_owner, end_owner = rebuild_owners()

        if i in end_owner and j in start_owner:
            ra = end_owner[i]
            rb = start_owner[j]
            if ra != rb and loads[ra] + loads[rb] <= capacity:
                merge_with_alignment(ra, rb, 0)
                merges_done += 1
        elif i in start_owner and j in end_owner:
            ra = start_owner[i]
            rb = end_owner[j]
            if ra != rb and loads[ra] + loads[rb] <= capacity:
                merge_with_alignment(ra, rb, 1)
                merges_done += 1
        elif i in end_owner and j in end_owner:
            ra = end_owner[i]
            rb = end_owner[j]
            if ra != rb and loads[ra] + loads[rb] <= capacity:
                merge_with_alignment(ra, rb, 2)
                merges_done += 1
        elif i in start_owner and j in start_owner:
            ra = start_owner[i]
            rb = start_owner[j]
            if ra != rb and loads[ra] + loads[rb] <= capacity:
                merge_with_alignment(ra, rb, 3)
                merges_done += 1

        if len([r for r in routes if r]) <= max(1, hint):
            # conservative: still allow some improvements, but stop early to avoid fragmentation
            if s <= 0:
                break

    routes = [r for r in routes if r]

    # ---------- Post-process: local improvements ----------
    for k in range(len(routes)):
        routes[k] = best_2opt(routes[k])

    routes = try_relocate(routes, max_passes=4)
    routes = try_exchange(routes, max_passes=2)

    # Final feasibility purge
    out = []
    for r in routes:
        if not r:
            continue
        if route_load(r) <= capacity:
            out.append(r)
    return out
